  axis lines=middle,
  grid=major,
  enlargelimits=false
]
\nextgroupplot[
  xlabel={horizontal variable},
  ylabel={$z$},
  title={Vertical traces are downward parabolas},
  legend pos=south east,
  xmin=-1, xmax=1,
  ymin=-9, ymax=1
]
